ractions":{"combination_prohibited":[{"drug_id":null,"display_name":"他の シウククエプト","clinical_symptom":"併用開始後数日以内に ヤクウ が報告されている。 (架空)","mechanism":"糞便排泄 を介した排泄競合により本剤の消失半減期が延長する可能性がある。 (架空)"}],"combination_caution":[{"drug_id":null,"display_name":"トガ 系薬剤","clinical_symptom":"併用により トクオア が発現又は悪化するおそれがある。 (架空)","mechanism":"併用薬との蛋白結合置換により、本剤の遊離型分率が上昇し ライセン を招くおそれがある。 (架空)"}]},"adverse_reactions":{"serious":[{"name":"ライセン","frequency":"unknown","symptom":"長期投与により ヤクウ 及び クレアチニン値 の変化が報告されている。 (架空)","initial_signs":"発現時の徴候として ドンイスリケス 及び ヘモグロビン値 の変動が報告されている。 (架空)","countermeasure":"重症例では イルアウク の投与と 超音波検査 による経過観察を行うこと。 (架空)"}],"other":{"over5_percent":["リングレル","イエヴィルクズ"],"between1_and5_percent":["リングレル"],"under1_percent":["リングレル"],"frequency_unknown":["ルクライジュンドイク"]}},"effects_on_lab_tests":[{"order":1,"sub_order":null,"content":"本剤の投与により 血糖値 が見かけ上変動することがあるため、検査値の解釈には注意を要する。 (架空)"}],"overdose":{"symptoms":"過量摂取により 血小板数 の変動を伴う ドンイスリケス が発現しうる。 (架空)","management":"血液透析や強制利尿の有効性は確立していないため、支持療法を行いつつ 血液検査 を継続管理する。 (架空)"},"administration_precautions":[{"order":1,"sub_order":null,"content":"- 服用時は十分量の水で服用するよう患者に指導すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 経鼻 以外の投与経路では本剤の有効性・安全性は確認されていない。 (架空)"}],"other_precautions":[{"order":1,"sub_order":null,"content":"長期投与時の安全性は 24 週間 までの試験で確認されている。 (架空)"}],"pharmacokinetics":{"blood_concentration":"健康成人に 385 μg を単回経口投与したとき、Cmax は 89.5 ng/mL、T1/2 は 14.5 時間 であった。 (架空)","absorption":"経口投与後、速やかに消化管から吸収され、1.0 時間 で最高血中濃度に到達する。 (架空)","distribution":"分布容積は 6.0 L/kg であり、組織移行性は中等度である。 (架空)","metabolism":"ピュセンリ の遺伝子多型により代謝速度が個体差を示す可能性がある。 (架空)","excretion":"糞便中排泄率は 0.8 % であり、腎機能低下時は用量調節を考慮する。 (架空)","parameters":[{"name":"Cmax","value":"6.1 μg/mL"},{"name":"T1/2","value":"11.5 時間"},{"name":"AUC","value":"27.0 μg・時/mL"}]},"clinical_results":[{"heading":"長期投与試験","content":"ジャマ 患者 400 例 例を対象とした二重盲検比較試験で有効率は**81.2 %**であった。 (架空)"},{"heading":"有効性","content":"チレウジ 患者 300 例 例を対象とした二重盲検比較試験で有効率は**40.1 %**であった。 (架空)"},{"heading":"長期投与試験","content":"長期投与試験では 3