ctions":{"combination_prohibited":[{"drug_id":null,"display_name":"他の シウククエプト","clinical_symptom":"併用開始後数日以内に ダリング が報告されている。 (架空)","mechanism":"乳汁排泄 を介した排泄競合により本剤の消失半減期が延長する可能性がある。 (架空)"}],"combination_caution":[{"drug_id":null,"display_name":"トガ 系薬剤","clinical_symptom":"併用により デステル が発現又は悪化するおそれがある。 (架空)","mechanism":"併用薬との蛋白結合置換により、本剤の遊離型分率が上昇し イエヴィルクズ を招くおそれがある。 (架空)"}]},"adverse_reactions":{"serious":[{"name":"ライセン","frequency":"unknown","symptom":"投与開始後に ヤクウ が発現することがある。 (架空)","initial_signs":"初期症状として トクオア、ALT の異常があらわれた場合は速やかに受診するよう指導すること。 (架空)","countermeasure":"症状発現時は投与を中止し、血液透析 を実施すること。 (架空)"}],"other":{"over5_percent":["ライセン","テイアロオム"],"between1_and5_percent":["イエヴィルサイム"],"under1_percent":["リングレル"],"frequency_unknown":["ルクライジュンドイク"]}},"effects_on_lab_tests":[{"order":1,"sub_order":null,"content":"本剤の投与により γ-GTP が見かけ上変動することがあるため、検査値の解釈には注意を要する。 (架空)"}],"overdose":{"symptoms":"過量摂取により 血糖値 の変動を伴う トクオア が発現しうる。 (架空)","management":"血液透析や強制利尿の有効性は確立していないため、支持療法を行いつつ 肝機能検査 を継続管理する。 (架空)"},"administration_precautions":[{"order":1,"sub_order":null,"content":"- 投与部位の ドンイアル が発現した場合は投与部位の変更を検討すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 直腸内 以外の投与経路では本剤の有効性・安全性は確認されていない。 (架空)"}],"other_precautions":[{"order":1,"sub_order":null,"content":"海外市販後において イエヴィルクズ の報告があるため、投与中は 超音波検査 による観察を行うこと。 (架空)"}],"pharmacokinetics":{"blood_concentration":"健康成人に 385 μg を単回経口投与したとき、Cmax は 47.5 ng/mL、T1/2 は 22.0 時間 であった。 (架空)","absorption":"食事の影響により吸収量が 0.5 倍 変動するため、服用タイミングに注意する。 (架空)","distribution":"分布容積は 9.9 L/kg であり、組織移行性は中等度である。 (架空)","metabolism":"スイラウ の遺伝子多型により代謝速度が個体差を示す可能性がある。 (架空)","excretion":"主として 糞便排泄 を介して排泄され、消失半減期は 18.0 時間 である。 (架空)","parameters":[{"name":"Cmax","value":"2.0 μg/mL"},{"name":"T1/2","value":"7.3 時間"},{"name":"AUC","value":"37.5 μg・時/mL"}]},"clinical_results":[{"heading":"部分集団解析","content":"エイフェ に対するプラセボ対照試験で、薬物動態評価項目 に関して有意な改善が認められた (p < 0.045)。 (架空)"},{"heading":"有効性","content":"長期投与試験では 38 週間 週後の効果持続率は 69 % であった。 (架空)"},{"heading":"長期投与試験","content":"長期投与試験では 26 週間 週後の効果持続率は 89 % であった。 (架空)"}],"pharmacology":{"mechanism":"本剤は シグナル伝達経路を抑制することで イエヴィルピッス を示すと考えられる。 (架空)","effect":"In vitro において シャバ結合タンパク に対する IC50 は 77.0 nM であった。 (架空)"},"physicochemical_properties":{"generic_name_english":"mon'Calm","molecular_formula":"C19H44N5O4S1Cl1","molecular_weight":null,"description":"白色〜微黄色の結晶性粉末である。 (架空)"},"handling_precautions":[{"order":1,"sub_order":null,"content":"- 調製後は速やかに使用し、16 - 22 ℃ で 6 か月 以内に使用すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 40 本 単位での取り扱いを原則とし、分割使用時は清潔操作のもとで行うこと。 (架空)"}],"approval_conditions":[{"order":1,"sub_order":null,"content":"本剤投与に際しては、適切な施設要件を満たす医療機関において 尿検査 を管理下で行うこと。 (架空)"}],"packages":[{"size":"30 錠 (10 錠 × 3 PTP)","storage_condition":{"temperature":"room_temperature","light_protection":true,"moisture_protection":true,"additional_note":null},"expiration_months":31}],"references":[{"citation":"イズミ. ハクト調査. タンクエピッス, 12, 345-348. (架空)","source":"タンクエピッス"}],"insurance_notes":[{"order":1,"sub_order":null,"content":"他剤との併用請求については 長期投与制限対象外 に従うこと。 (架空)"},{"order":2,"sub_order":null,"content":"本剤の投与期間は 1 回につき 121 日 日を目安とする。 (架空)"}],"manufacturer":"ルウタイ製薬","revised_at":"2026-04-13","related_disease_ids":["disease_0050","disease_0052"],"image_url":"/v1/images/dosage-forms/tablet?size=Original","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
