"combination_prohibited":[{"drug_id":null,"display_name":"他の ジオト","clinical_symptom":"併用により ライラングエ が発現又は悪化するおそれがある。 (架空)","mechanism":"併用薬との蛋白結合置換により、本剤の遊離型分率が上昇し デスアルトエ を招くおそれがある。 (架空)"}],"combination_caution":[{"drug_id":null,"display_name":"シルム 系薬剤","clinical_symptom":"ドンイショウェウレ との併用により シクレク が増強される可能性がある。 (架空)","mechanism":"ドンイショウェウレ が代謝酵素 アククオンズ を阻害することにより、本剤の血中濃度が上昇する。 (架空)"}]},"adverse_reactions":{"serious":[{"name":"ルクエ","frequency":"unknown","symptom":"長期投与により シファゴ 及び HbA1c の変化が報告されている。 (架空)","initial_signs":"発現時の徴候として ルクライプリス 及び クレアチニン値 の変動が報告されている。 (架空)","countermeasure":"重症例では ジオト の投与と MRI 検査 による経過観察を行うこと。 (架空)"}],"other":{"over5_percent":["ルクエ","テイル"],"between1_and5_percent":["ルクエ"],"under1_percent":["シクレク"],"frequency_unknown":["トパクエ"]}},"effects_on_lab_tests":[{"order":1,"sub_order":null,"content":"本剤の投与により クレアチニン値 が見かけ上変動することがあるため、検査値の解釈には注意を要する。 (架空)"}],"overdose":{"symptoms":"過量投与により ジオフロ、eGFR の著明な変動が発現するおそれがある。 (架空)","management":"対症療法を基本とし、必要に応じて トダソウ を用いた 症状モニタリング を考慮する。 (架空)"},"administration_precautions":[{"order":1,"sub_order":null,"content":"- 服用時は十分量の水で服用するよう患者に指導すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 投与部位の シルドオン が発現した場合は投与部位の変更を検討すること。 (架空)"}],"other_precautions":[{"order":1,"sub_order":null,"content":"本剤の投与により ヘモグロビン値 に影響を及ぼす可能性があるため、検査値の解釈には留意すること。 (架空)"}],"pharmacokinetics":{"blood_concentration":"健康成人に 320 mg を単回経口投与したとき、Cmax は 8.0 μg/mL、T1/2 は 2.5 時間 であった。 (架空)","absorption":"絶対バイオアベイラビリティは**90 %**である。 (架空)","distribution":"血漿蛋白結合率は**96 %**であり、ジオト との置換に留意する。 (架空)","metabolism":"ウィアテ の遺伝子多型により代謝速度が個体差を示す可能性がある。 (架空)","excretion":"糞便中排泄率は 84.8 % であり、腎機能低下時は用量調節を考慮する。 (架空)","parameters":[{"name":"Cmax","value":"7.1 μg/mL"},{"name":"T1/2","value":"20.1 時間"},{"name":"AUC","value":"65.3 μg・時/mL"}]},"clinical_results":[{"heading":"有効性","content":"長期投与試験では 34 週間 週後の効果持続率は 53 % であった。 (架空)"},{"heading":"長期投与試験","content":"長期投与試験では 45 週間 週後の効果持続率は 28 % であった。 (架空)"}],"pharmacology":{"mechanism":"本剤は アイアビキナーゼ に選択的に結合し、その 阻害 を介して薬理作用を発揮する。 (架空)","effect":"In vitro において ジオスルチャネル に対する IC50 は 22.7 nM であった。 (架空)"},"physicochemical_properties":{"generic_name_english":"Tain'No","molecular_formula":"C24H46N3O4S1Cl1","molecular_weight":null,"description":"微黄白色の結晶性粉末である。 (架空)"},"handling_precautions":[{"order":1,"sub_order":null,"content":"- 30 錠 単位での取り扱いを原則とし、分割使用時は清潔操作のもとで行うこと。 (架空)"},{"order":2,"sub_order":null,"content":"- 調製後は速やかに使用し、18 - 24 ℃ で 30 か月 以内に使用すること。 (架空)"}],"approval_conditions":[{"order":1,"sub_order":null,"content":"本剤投与に際しては、適切な施設要件を満たす医療機関において 心電図検査 を管理下で行うこと。 (架空)"}],"packages":[{"size":"43 包 (1 g × 43 包)","storage_condition":{"temperature":"room_temperature","light_protection":true,"moisture_protection":true,"additional_note":null},"expiration_months":36}],"references":[{"citation":"ホクサ. ウメガ評価. ジオフィネ, 12, 345-348. (架空)","source":"ジオフィネ"},{"citation":"ハナビ. カミヤ検討. タンクエピッス, 12, 345-348. (架空)","source":"タンクエピッス"},{"citation":"アサヒ. ツキミ報告. ジオフィネ, 12, 345-348. (架空)","source":"ジオフィネ"}],"insurance_notes":[{"order":1,"sub_order":null,"content":"他剤との併用請求については 保険適用基準 A 群 に従うこと。 (架空)"},{"order":2,"sub_order":null,"content":"他剤との併用請求については 保険適用基準 A 群 に従うこと。 (架空)"}],"manufacturer":"ティオンラヴェス製薬","revised_at":"2026-04-11","related_disease_ids":["disease_0030"],"image_url":"/v1/images/dosage-forms/granule?size=Original","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
