ons":[{"category":"hepatic_impairment","note":"高齢者 への投与経験は限られている。腎機能検査 を管理しながら慎重に投与する。 (架空)"}],"interactions":{"combination_prohibited":[{"drug_id":null,"display_name":"他の ライスイケスモレ","clinical_symptom":"ライスイケスモレ との併用により テイアロオム が増強される可能性がある。 (架空)","mechanism":"ライスイケスモレ が代謝酵素 ウィアテ を阻害することにより、本剤の血中濃度が上昇する。 (架空)"}],"combination_caution":[{"drug_id":null,"display_name":"リングケト 系薬剤","clinical_symptom":"併用開始後数日以内に トクオア が報告されている。 (架空)","mechanism":"呼気排泄 を介した排泄競合により本剤の消失半減期が延長する可能性がある。 (架空)"}]},"adverse_reactions":{"serious":[{"name":"テイアロオム","frequency":"under_1_percent","symptom":"長期投与により イルヘク 及び γ-GTP の変化が報告されている。 (架空)","initial_signs":"発現時の徴候として ヤクウ 及び 血小板数 の変動が報告されている。 (架空)","countermeasure":"重症例では ルクライラ の投与と 超音波検査 による経過観察を行うこと。 (架空)"},{"name":"シスレ","frequency":"over_5_percent","symptom":"投与開始後に ライロウ が発現することがある。 (架空)","initial_signs":"初期症状として イルヘク、ヘモグロビン値 の異常があらわれた場合は速やかに受診するよう指導すること。 (架空)","countermeasure":"症状発現時は投与を中止し、輸液管理 を実施すること。 (架空)"}],"other":{"over5_percent":["イエヴィルメルル","シスレ"],"between1_and5_percent":["イエヴィルメルル"],"under1_percent":["ルクライジュンドイク"],"frequency_unknown":["イエヴィルサイム"]}},"effects_on_lab_tests":[{"order":1,"sub_order":null,"content":"本剤の投与により CRP が見かけ上変動することがあるため、検査値の解釈には注意を要する。 (架空)"},{"order":2,"sub_order":null,"content":"CRP が一過性に上昇することがあるため、投与中は 心電図検査 を定期的に行うこと。 (架空)"}],"overdose":{"symptoms":"過剰投与時には急性の イエヴィルクズ が報告されている。 (架空)","management":"過量投与の疑いがある場合は、胃洗浄等の 投与中止 を実施し、尿検査 でモニタリングする。 (架空)"},"administration_precautions":[{"order":1,"sub_order":null,"content":"- 投与部位の ドンイスリケス が発現した場合は投与部位の変更を検討すること。 (架空)"}],"other_precautions":[{"order":1,"sub_order":null,"content":"海外市販後において シスレ の報告があるため、投与中は 肝機能検査 による観察を行うこと。 (架空)"},{"order":2,"sub_order":null,"content":"長期投与時の安全性は 52 週間 までの試験で確認されている。 (架空)"}],"pharmacokinetics":{"blood_concentration":"投与後の血中濃度推移は 母集団薬物動態モデルで良好に記述される。 (架空)","absorption":"経口投与後、速やかに消化管から吸収され、6.5 時間 で最高血中濃度に到達する。 (架空)","distribution":"血漿蛋白結合率は**85 %**であり、ライスイケスモレ との置換に留意する。 (架空)","metabolism":"セントメ の遺伝子多型により代謝速度が個体差を示す可能性がある。 (架空)","excretion":"投与量の 17.5 % が尿中に未変化体として排泄される。 (架空)","parameters":[{"name":"Cmax","value":"7.2 μg/mL"},{"name":"T1/2","value":"15.8 時間"},{"name":"AUC","value":"29.9 μg・時/mL"}]},"clinical_results":[{"heading":"投与継続性","content":"長期投与試験では 18 週間 週後の効果持続率は 71 % であった。 (架空)"},{"heading":"用量反応","content":"ルイロジ に対するプラセボ対照試験で、主要評価項目 に関して有意な改善が認められた (p < 0.040)。 (架空)"}],"pharmacology":{"mechanism":"本剤は 免疫応答経路を抑制することで テイスイケ を示すと考えられる。 (架空)","effect":"In vitro において ライオルンクフタンパク に対する IC50 は 19.7 nM であった。 (架空)"},"physicochemical_properties":{"generic_name_english":"Chil'Rar","molecular_formula":"C14H23N2O7","molecular_weight":null,"description":"白色〜淡黄色の粉末である。 (架空)"},"handling_precautions":[{"order":1,"sub_order":null,"content":"- 50 錠 単位での取り扱いを原則とし、分割使用時は清潔操作のもとで行うこと。 (架空)"}],"approval_conditions":[{"order":1,"sub_order":null,"content":"本剤の安全性に関する 市販後臨床試験 を市販後に実施すること。 (架空)"},{"order":2,"sub_order":null,"content":"本剤の適正使用に関して医師等を対象とした 処方監査研修 を実施し、適切な情報提供を行うこと。 (架空)"}],"packages":[{"size":"93 包 (3 g × 93 包)","storage_condition":{"temperature":"room_temperature","light_protection":false,"moisture_protection":true,"additional_note":null},"expiration_months":60}],"references":[{"citation":"ヨツバ. ヒモロ検討. トイムグ, 12, 345-348. (架空)","source":"トイムグ"},{"citation":"セキネ. セノミ評価. トイムグ, 12, 345-348. (架空)","source":"トイムグ"}],"insurance_notes":[{"order":1,"sub_order":null,"content":"本剤の保険請求にあたっては、ルイロジ の確定診断根拠を診療録に記載すること。 (架空)"}],"manufacturer":"ハデミク製薬","revised_at":"2026-04-06","related_disease_ids":["disease_0019"],"image_url":"/v1/images/dosage-forms/granule?size=Original","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
