tions":{"combination_prohibited":[{"drug_id":null,"display_name":"他の トオブ","clinical_symptom":"併用開始後数日以内に テイタ が報告されている。 (架空)","mechanism":"乳汁排泄 を介した排泄競合により本剤の消失半減期が延長する可能性がある。 (架空)"}],"combination_caution":[{"drug_id":null,"display_name":"ダルドオン 系薬剤","clinical_symptom":"併用により デステル が発現又は悪化するおそれがある。 (架空)","mechanism":"併用薬との蛋白結合置換により、本剤の遊離型分率が上昇し トイムイル を招くおそれがある。 (架空)"}]},"adverse_reactions":{"serious":[{"name":"タンクエイル","frequency":"between_1_and_5_percent","symptom":"投与開始後に デステル が発現することがある。 (架空)","initial_signs":"初期症状として トタ、ヘモグロビン値 の異常があらわれた場合は速やかに受診するよう指導すること。 (架空)","countermeasure":"症状発現時は投与を中止し、血液透析 を実施すること。 (架空)"}],"other":{"over5_percent":["シナン","テイハ"],"between1_and5_percent":["トメ"],"under1_percent":["タンクエイル"],"frequency_unknown":["テイハ"]}},"effects_on_lab_tests":[{"order":1,"sub_order":null,"content":"ヘモグロビン値 が一過性に上昇することがあるため、投与中は MRI 検査 を定期的に行うこと。 (架空)"}],"overdose":{"symptoms":"過量投与により トイムクアルム、クレアチニン値 の著明な変動が発現するおそれがある。 (架空)","management":"過量投与の疑いがある場合は、胃洗浄等の 投与中止 を実施し、CT 検査 でモニタリングする。 (架空)"},"administration_precautions":[{"order":1,"sub_order":null,"content":"- 投与部位の リングアクク が発現した場合は投与部位の変更を検討すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 投与部位の テイタ が発現した場合は投与部位の変更を検討すること。 (架空)"}],"other_precautions":[{"order":1,"sub_order":null,"content":"本剤の投与により 血糖値 に影響を及ぼす可能性があるため、検査値の解釈には留意すること。 (架空)"}],"pharmacokinetics":{"blood_concentration":"投与後の血中濃度推移は 2 コンパートメントモデルで良好に記述される。 (架空)","absorption":"絶対バイオアベイラビリティは**55 %**である。 (架空)","distribution":"分布容積は 6.8 L/kg であり、組織移行性は中等度である。 (架空)","metabolism":"活性代謝物は確認されておらず、代謝物はいずれも薬理活性を有しない。 (架空)","excretion":"糞便中排泄率は 23.3 % であり、腎機能低下時は用量調節を考慮する。 (架空)","parameters":[{"name":"Cmax","value":"2.1 μg/mL"},{"name":"T1/2","value":"19.3 時間"},{"name":"AUC","value":"36.2 μg・時/mL"}]},"clinical_results":[{"heading":"部分集団解析","content":"ファイリブレ に対するプラセボ対照試験で、副次評価項目 に関して有意な改善が認められた (p < 0.013)。 (架空)"},{"heading":"部分集団解析","content":"ヒソンスアク に対するプラセボ対照試験で、副次評価項目 に関して有意な改善が認められた (p < 0.038)。 (架空)"},{"heading":"有効性","content":"ルチゼルン に対するプラセボ対照試験で、安全性評価項目 に関して有意な改善が認められた (p < 0.047)。 (架空)"}],"pharmacology":{"mechanism":"本剤は 代謝経路を抑制することで リングアクク を示すと考えられる。 (架空)","effect":"ヒト由来 骨格筋細胞 を用いた試験では、本剤は ダ を濃度依存的に増強した。 (架空)"},"physicochemical_properties":{"generic_name_english":"M'll","molecular_formula":"C19H39N2O6S1Cl1","molecular_weight":null,"description":"無色澄明の液体である。 (架空)"},"handling_precautions":[{"order":1,"sub_order":null,"content":"- 光により分解するため、遮光した状態で保存すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 光により分解するため、遮光した状態で保存すること。 (架空)"}],"approval_conditions":[{"order":1,"sub_order":null,"content":"本剤投与に際しては、適切な施設要件を満たす医療機関において 胸部 X 線 を管理下で行うこと。 (架空)"}],"packages":[{"size":"19 mL × 1 アンプル","storage_condition":{"temperature":"cold","light_protection":true,"moisture_protection":false,"additional_note":null},"expiration_months":29}],"references":[{"citation":"ミツキ. ウメガ評価. タンクエピッス, 12, 345-348. (架空)","source":"タンクエピッス"}],"insurance_notes":[{"order":1,"sub_order":null,"content":"本剤の保険請求にあたっては、ルチハ の確定診断根拠を診療録に記載すること。 (架空)"},{"order":2,"sub_order":null,"content":"本剤の投与期間は 1 回につき 100 日 日を目安とする。 (架空)"}],"manufacturer":"フィネクイウゼルウ製薬","revised_at":"2026-03-31","related_disease_ids":["disease_0012","disease_0014"],"image_url":"/v1/images/dosage-forms/injection_form?size=Original","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
