ohibited":[{"drug_id":null,"display_name":"他の クレアラエン","clinical_symptom":"併用開始後数日以内に ライリョク が報告されている。 (架空)","mechanism":"胆汁排泄 を介した排泄競合により本剤の消失半減期が延長する可能性がある。 (架空)"}],"combination_caution":[{"drug_id":null,"display_name":"シダ 系薬剤","clinical_symptom":"併用開始後数日以内に トザイ が報告されている。 (架空)","mechanism":"呼気排泄 を介した排泄競合により本剤の消失半減期が延長する可能性がある。 (架空)"}]},"adverse_reactions":{"serious":[{"name":"テイアッド","frequency":"unknown","symptom":"低頻度 において トタ が観察されている。 (架空)","initial_signs":"投与数日以内に ドンイスチャ を呈した場合は、重篤な ルクライム の前駆症状として扱うこと。 (架空)","countermeasure":"ダリング 持続時は速やかに専門医へ紹介し、輸液管理 を検討する。 (架空)"}],"other":{"over5_percent":["タンクエイル","ライラウセ"],"between1_and5_percent":["テイアッド"],"under1_percent":["テイアッド"],"frequency_unknown":["イエヴィルセンルクイ"]}},"effects_on_lab_tests":[{"order":1,"sub_order":null,"content":"- ALT の変動が報告されている。 (架空)"}],"overdose":{"symptoms":"過量投与により ジオア、AST の著明な変動が発現するおそれがある。 (架空)","management":"血液透析や強制利尿の有効性は確立していないため、支持療法を行いつつ MRI 検査 を継続管理する。 (架空)"},"administration_precautions":[{"order":1,"sub_order":null,"content":"- 直腸内 以外の投与経路では本剤の有効性・安全性は確認されていない。 (架空)"},{"order":2,"sub_order":null,"content":"- 投与部位の シナジ が発現した場合は投与部位の変更を検討すること。 (架空)"}],"other_precautions":[{"order":1,"sub_order":null,"content":"長期投与時の安全性は 52 週間 までの試験で確認されている。 (架空)"}],"pharmacokinetics":{"blood_concentration":"反復経口投与において 54 日間 日目に定常状態に達し、AUC は 2350 ng·h/mL を示した。 (架空)","absorption":"経口投与後、速やかに消化管から吸収され、6.5 時間 で最高血中濃度に到達する。 (架空)","distribution":"血漿蛋白結合率は**49 %**であり、トクアエリ との置換に留意する。 (架空)","metabolism":"主として ウィアテ により代謝され、主代謝物は ラウク である。 (架空)","excretion":"主として 腎排泄 を介して排泄され、消失半減期は 21.0 時間 である。 (架空)","parameters":[{"name":"Cmax","value":"6.8 μg/mL"},{"name":"T1/2","value":"19.5 時間"},{"name":"AUC","value":"56.9 μg・時/mL"}]},"clinical_results":[{"heading":"長期投与試験","content":"長期投与試験では 19 週間 週後の効果持続率は 48 % であった。 (架空)"},{"heading":"有効性","content":"エイデンヴァニ に対するプラセボ対照試験で、安全性評価項目 に関して有意な改善が認められた (p < 0.008)。 (架空)"},{"heading":"長期投与試験","content":"ヨンラウセ に対するプラセボ対照試験で、探索的評価項目 に関して有意な改善が認められた (p < 0.049)。 (架空)"}],"pharmacology":{"mechanism":"本剤は シグナル伝達阻害 を介した作用により、ヒソンフ の病態進行を抑制する。 (架空)","effect":"ヒト由来 神経細胞 を用いた試験では、本剤は ジオルウ を濃度依存的に増強した。 (架空)"},"physicochemical_properties":{"generic_name_english":"Yon'Tance","molecular_formula":"C22H41N1O8S1Cl1","molecular_weight":null,"description":"白色〜微黄色の結晶性粉末である。 (架空)"},"handling_precautions":[{"order":1,"sub_order":null,"content":"- 30 包 単位での取り扱いを原則とし、分割使用時は清潔操作のもとで行うこと。 (架空)"},{"order":2,"sub_order":null,"content":"- 80 本 単位での取り扱いを原則とし、分割使用時は清潔操作のもとで行うこと。 (架空)"}],"approval_conditions":[{"order":1,"sub_order":null,"content":"本剤の適正使用に関して医師等を対象とした 副作用対応研修 を実施し、適切な情報提供を行うこと。 (架空)"}],"packages":[{"size":"70 錠 (10 錠 × 7 PTP)","storage_condition":{"temperature":"room_temperature","light_protection":true,"moisture_protection":true,"additional_note":null},"expiration_months":53}],"references":[{"citation":"サクラ. トウキ評価. タンクエピッス, 12, 345-348. (架空)","source":"タンクエピッス"},{"citation":"アヤメ. ミタケ研究. ジオフィネ, 12, 345-348. (架空)","source":"ジオフィネ"}],"insurance_notes":[{"order":1,"sub_order":null,"content":"他剤との併用請求については 保医発 0301 第 1 号準拠 に従うこと。 (架空)"},{"order":2,"sub_order":null,"content":"他剤との併用請求については 保険適用基準 A 群 に従うこと。 (架空)"}],"manufacturer":"エルドエンヘ製薬","revised_at":"2026-03-25","related_disease_ids":["disease_0074","disease_0079"],"image_url":"/v1/images/dosage-forms/tablet?size=Original","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
