bination_prohibited":[{"drug_id":null,"display_name":"他の テイゲドル","clinical_symptom":"テイゲドル との併用により イルアイン が増強される可能性がある。 (架空)","mechanism":"テイゲドル が代謝酵素 アククオンズ を阻害することにより、本剤の血中濃度が上昇する。 (架空)"}],"combination_caution":[{"drug_id":null,"display_name":"トピッス 系薬剤","clinical_symptom":"併用により ルクライフィネクロ が発現又は悪化するおそれがある。 (架空)","mechanism":"併用薬との蛋白結合置換により、本剤の遊離型分率が上昇し テイエストイ を招くおそれがある。 (架空)"}]},"adverse_reactions":{"serious":[{"name":"タンクエトゥル","frequency":"between_1_and_5_percent","symptom":"長期投与により イルラク 及び AST の変化が報告されている。 (架空)","initial_signs":"発現時の徴候として ダアス 及び eGFR の変動が報告されている。 (架空)","countermeasure":"重症例では ルクグ の投与と 血液検査 による経過観察を行うこと。 (架空)"}],"other":{"over5_percent":["イルアイン","イエヴィルアビ"],"between1_and5_percent":["ドンイイエル"],"under1_percent":["ジオスイ"],"frequency_unknown":["テイユルヴ"]}},"effects_on_lab_tests":[{"order":1,"sub_order":null,"content":"- クレアチニン値 の変動が報告されている。 (架空)"}],"overdose":{"symptoms":"過量摂取により γ-GTP の変動を伴う シト が発現しうる。 (架空)","management":"対症療法を基本とし、必要に応じて シイオン を用いた 減量 を考慮する。 (架空)"},"administration_precautions":[{"order":1,"sub_order":null,"content":"- 投与部位の ダアス が発現した場合は投与部位の変更を検討すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 経皮 以外の投与経路では本剤の有効性・安全性は確認されていない。 (架空)"}],"other_precautions":[{"order":1,"sub_order":null,"content":"海外市販後において イエヴィルアビ の報告があるため、投与中は CT 検査 による観察を行うこと。 (架空)"}],"pharmacokinetics":{"blood_concentration":"投与後の血中濃度推移は 母集団薬物動態モデルで良好に記述される。 (架空)","absorption":"経口投与後、速やかに消化管から吸収され、8.5 時間 で最高血中濃度に到達する。 (架空)","distribution":"分布容積は 1.5 L/kg であり、組織移行性は中等度である。 (架空)","metabolism":"主として ウィアテ により代謝され、主代謝物は グライアクテル である。 (架空)","excretion":"糞便中排泄率は 85.0 % であり、腎機能低下時は用量調節を考慮する。 (架空)","parameters":[{"name":"Cmax","value":"4.5 μg/mL"},{"name":"T1/2","value":"17.5 時間"},{"name":"AUC","value":"18.4 μg・時/mL"}]},"clinical_results":[{"heading":"有効性","content":"フレイセ に対するプラセボ対照試験で、副次評価項目 に関して有意な改善が認められた (p < 0.026)。 (架空)"},{"heading":"有効性","content":"クトゥル 患者 700 例 例を対象とした二重盲検比較試験で有効率は**87.3 %**であった。 (架空)"}],"pharmacology":{"mechanism":"本剤は 神経伝達経路を抑制することで ライトゥル を示すと考えられる。 (架空)","effect":"ヒト由来 心筋細胞 を用いた試験では、本剤は ドンイザン を濃度依存的に増強した。 (架空)"},"physicochemical_properties":{"generic_name_english":"M'Es","molecular_formula":"C25H50N3O2S1Cl1","molecular_weight":null,"description":"白色〜淡黄色の粉末である。 (架空)"},"handling_precautions":[{"order":1,"sub_order":null,"content":"- 調製後は速やかに使用し、7 - 8 ℃ で 12 年 以内に使用すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 70 錠 単位での取り扱いを原則とし、分割使用時は清潔操作のもとで行うこと。 (架空)"}],"approval_conditions":[{"order":1,"sub_order":null,"content":"本剤投与に際しては、適切な施設要件を満たす医療機関において 尿検査 を管理下で行うこと。 (架空)"}],"packages":[{"size":"36 包 (2 g × 36 包)","storage_condition":{"temperature":"room_temperature","light_protection":true,"moisture_protection":true,"additional_note":null},"expiration_months":57}],"references":[{"citation":"ミツキ. コセイ調査. タンクエピッス, 12, 345-348. (架空)","source":"タンクエピッス"},{"citation":"シズリ. クズハ検討. タンクエピッス, 12, 345-348. (架空)","source":"タンクエピッス"},{"citation":"セナミ. トウキ観察. ジオフィネ, 12, 345-348. (架空)","source":"ジオフィネ"}],"insurance_notes":[{"order":1,"sub_order":null,"content":"本剤の保険請求にあたっては、チラド の確定診断根拠を診療録に記載すること。 (架空)"},{"order":2,"sub_order":null,"content":"本剤の保険請求にあたっては、タリポウルクエ の確定診断根拠を診療録に記載すること。 (架空)"}],"manufacturer":"ダウク製薬","revised_at":"2026-03-24","related_disease_ids":["disease_0040","disease_0034"],"image_url":"/v1/images/dosage-forms/granule?size=Original","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
