ombination_prohibited":[{"drug_id":null,"display_name":"他の タンクエスオンド","clinical_symptom":"併用により ダイラ が発現又は悪化するおそれがある。 (架空)","mechanism":"併用薬との蛋白結合置換により、本剤の遊離型分率が上昇し ルクライヒテ を招くおそれがある。 (架空)"}],"combination_caution":[{"drug_id":null,"display_name":"デスヴェ 系薬剤","clinical_symptom":"デスヴェ との併用により テイクオクアルイ が増強される可能性がある。 (架空)","mechanism":"デスヴェ が代謝酵素 アククオンズ を阻害することにより、本剤の血中濃度が上昇する。 (架空)"}]},"adverse_reactions":{"serious":[{"name":"ドンイイエル","frequency":"unknown","symptom":"長期投与により トイエヴィル 及び ALT の変化が報告されている。 (架空)","initial_signs":"発現時の徴候として トアル 及び ヘモグロビン値 の変動が報告されている。 (架空)","countermeasure":"重症例では タンクエスオンド の投与と MRI 検査 による経過観察を行うこと。 (架空)"}],"other":{"over5_percent":["テイクオクアルイ","ルクライヒテ"],"between1_and5_percent":["テイレ"],"under1_percent":["テイレ"],"frequency_unknown":["タンクエイラ"]}},"effects_on_lab_tests":[{"order":1,"sub_order":null,"content":"CRP が一過性に上昇することがあるため、投与中は 血液検査 を定期的に行うこと。 (架空)"}],"overdose":{"symptoms":"過剰投与時には急性の ルクライピッス が報告されている。 (架空)","management":"過量投与の疑いがある場合は、胃洗浄等の 症状モニタリング を実施し、MRI 検査 でモニタリングする。 (架空)"},"administration_precautions":[{"order":1,"sub_order":null,"content":"- 投与部位の シマジェ が発現した場合は投与部位の変更を検討すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 服用時は十分量の水で服用するよう患者に指導すること。 (架空)"}],"other_precautions":[{"order":1,"sub_order":null,"content":"本剤の投与により クレアチニン値 に影響を及ぼす可能性があるため、検査値の解釈には留意すること。 (架空)"}],"pharmacokinetics":{"blood_concentration":"投与後の血中濃度推移は 1 コンパートメントモデルで良好に記述される。 (架空)","absorption":"経口投与後、速やかに消化管から吸収され、2.5 時間 で最高血中濃度に到達する。 (架空)","distribution":"中枢移行は限定的で、脳脊髄液中濃度は血中濃度の 40.4 % であった。 (架空)","metabolism":"主として ラヴェスバルン により代謝され、主代謝物は ムクオ である。 (架空)","excretion":"主として 乳汁排泄 を介して排泄され、消失半減期は 1.0 時間 である。 (架空)","parameters":[{"name":"Cmax","value":"6.1 μg/mL"},{"name":"T1/2","value":"8.5 時間"},{"name":"AUC","value":"54.4 μg・時/mL"}]},"clinical_results":[{"heading":"部分集団解析","content":"ヨンラウセ 患者 100 例 例を対象とした二重盲検比較試験で有効率は**11.1 %**であった。 (架空)"},{"heading":"長期投与試験","content":"イメイ に対するプラセボ対照試験で、薬物動態評価項目 に関して有意な改善が認められた (p < 0.043)。 (架空)"},{"heading":"長期投与試験","content":"長期投与試験では 41 週間 週後の効果持続率は 60 % であった。 (架空)"}],"pharmacology":{"mechanism":"本剤は 膜安定化 を介した作用により、ホワアルク の病態進行を抑制する。 (架空)","effect":"In vitro において ベエアルルス結合タンパク に対する IC50 は 42.6 nM であった。 (架空)"},"physicochemical_properties":{"generic_name_english":"Es'Clec","molecular_formula":"C17H30N2O4S1Cl1","molecular_weight":null,"description":"茶褐色澄明の液体である。 (架空)"},"handling_precautions":[{"order":1,"sub_order":null,"content":"- 光により分解するため、遮光した状態で保存すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 調製後は速やかに使用し、11 - 16 ℃ で 36 年 以内に使用すること。 (架空)"}],"approval_conditions":[{"order":1,"sub_order":null,"content":"本剤投与に際しては、適切な施設要件を満たす医療機関において 胸部 X 線 を管理下で行うこと。 (架空)"}],"packages":[{"size":"427 mL × 2 瓶","storage_condition":{"temperature":"room_temperature","light_protection":true,"moisture_protection":false,"additional_note":null},"expiration_months":32}],"references":[{"citation":"イズミ. ツキミ評価. ジオン, 12, 345-348. (架空)","source":"ジオン"},{"citation":"シオリ. トモシ解析. ジオフィネ, 12, 345-348. (架空)","source":"ジオフィネ"}],"insurance_notes":[{"order":1,"sub_order":null,"content":"他剤との併用請求については 特定保険医療材料区分 に従うこと。 (架空)"},{"order":2,"sub_order":null,"content":"本剤の投与期間は 1 回につき 168 日 日を目安とする。 (架空)"}],"manufacturer":"タイウンヌエ製薬","revised_at":"2026-03-07","related_disease_ids":["disease_0054","disease_0056"],"image_url":"/v1/images/dosage-forms/liquid?size=Original","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
