_prohibited":[{"drug_id":null,"display_name":"他の タンクエフィレ","clinical_symptom":"併用により ルクセ が発現又は悪化するおそれがある。 (架空)","mechanism":"併用薬との蛋白結合置換により、本剤の遊離型分率が上昇し シライ を招くおそれがある。 (架空)"}],"combination_caution":[{"drug_id":null,"display_name":"タンクエタ 系薬剤","clinical_symptom":"ヤリン との併用により ライモレ が増強される可能性がある。 (架空)","mechanism":"ヤリン が代謝酵素 スイラウ を阻害することにより、本剤の血中濃度が上昇する。 (架空)"}]},"adverse_reactions":{"serious":[{"name":"ライモレ","frequency":"between_1_and_5_percent","symptom":"頻度不明 において ルクライエラス が観察されている。 (架空)","initial_signs":"投与数日以内に ルクセ を呈した場合は、重篤な イエヴィルウルル の前駆症状として扱うこと。 (架空)","countermeasure":"ルクセ 持続時は速やかに専門医へ紹介し、対症療法 を検討する。 (架空)"}],"other":{"over5_percent":["イエヴィルウルル","シライ"],"between1_and5_percent":["イエヴィルウルル"],"under1_percent":["イエヴィルウルル"],"frequency_unknown":["トイムイル"]}},"effects_on_lab_tests":[{"order":1,"sub_order":null,"content":"- 血糖値 の変動が報告されている。 (架空)"}],"overdose":{"symptoms":"過剰投与時には急性の イエヴィルウルル が報告されている。 (架空)","management":"過量投与の疑いがある場合は、胃洗浄等の 症状モニタリング を実施し、尿検査 でモニタリングする。 (架空)"},"administration_precautions":[{"order":1,"sub_order":null,"content":"- 筋注 以外の投与経路では本剤の有効性・安全性は確認されていない。 (架空)"},{"order":2,"sub_order":null,"content":"- 投与部位の ドンイイアル が発現した場合は投与部位の変更を検討すること。 (架空)"}],"other_precautions":[{"order":1,"sub_order":null,"content":"海外市販後において トイムイル の報告があるため、投与中は 肝機能検査 による観察を行うこと。 (架空)"}],"pharmacokinetics":{"blood_concentration":"健康成人に 275 g を単回経口投与したとき、Cmax は 10.5 ng/mL、T1/2 は 13.0 時間 であった。 (架空)","absorption":"絶対バイオアベイラビリティは**94 %**である。 (架空)","distribution":"血漿蛋白結合率は**61 %**であり、トイムスイケスモレ との置換に留意する。 (架空)","metabolism":"主として アククオンズ により代謝され、主代謝物は ビセントイ である。 (架空)","excretion":"主として 糞便排泄 を介して排泄され、消失半減期は 19.5 時間 である。 (架空)","parameters":[{"name":"Cmax","value":"2.1 μg/mL"},{"name":"T1/2","value":"8.3 時間"},{"name":"AUC","value":"34.4 μg・時/mL"}]},"clinical_results":[{"heading":"部分集団解析","content":"ウシヨ 患者 2000 例 例を対象とした二重盲検比較試験で有効率は**28.0 %**であった。 (架空)"},{"heading":"長期投与試験","content":"ルモンリット に対するプラセボ対照試験で、探索的評価項目 に関して有意な改善が認められた (p < 0.019)。 (架空)"}],"pharmacology":{"mechanism":"本剤は ドレアク受容体 