properties":{"generic_name_english":"Ose'Tain","molecular_formula":"C22H38N5O2S1Cl1","molecular_weight":null,"description":"微黄白色の結晶性粉末である。 (架空)"},"handling_precautions":[{"order":1,"sub_order":null,"content":"- 光により分解するため、遮光した状態で保存すること。 (架空)"},{"order":2,"sub_order":null,"content":"- 光により分解するため、遮光した状態で保存すること。 (架空)"}],"approval_conditions":[{"order":1,"sub_order":null,"content":"本剤の適正使用に関して医師等を対象とした 適正使用研修 を実施し、適切な情報提供を行うこと。 (架空)"}],"packages":[{"size":"69 包 (1 g × 69 包)","storage_condition":{"temperature":"room_temperature","light_protection":true,"moisture_protection":true,"additional_note":null},"expiration_months":32}],"references":[{"citation":"ヤマセ. ホクメイ観察. ジオフィネ, 12, 345-348. (架空)","source":"ジオフィネ"},{"citation":"トキワ. ヤヨイ比較. ジオフィネ, 12, 345-348. (架空)","source":"ジオフィネ"}],"insurance_notes":[{"order":1,"sub_order":null,"content":"本剤の投与期間は 1 回につき 71 日 日を目安とする。 (架空)"},{"order":2,"sub_order":null,"content":"本剤の投与期間は 1 回につき 128 日 日を目安とする。 (架空)"}],"manufacturer":"キイム製薬","revised_at":"2026-02-19","related_disease_ids":["disease_0001"],"image_url":"/v1/images/dosage-forms/granule?size=Original","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
