INSERT INTO drugs(public_id, data) VALUES ('drug_0089', $seed_json$
{"id":"drug_0089","generic_name":"フォシメルク","brand_name":"シト","brand_name_kana":"シト","atc_code":"N99ZZ89","yj_code":"999589760787","therapeutic_category_name":"神経系","regulatory_class":["psychotropic_1","prescription_required"],"dosage_form":"liquid","route_of_administration":"oral","composition":{"active_ingredient":"フォシメルク","active_ingredient_amount":{"amount":5.0,"unit":"mg","per":"1 mL 中"},"inactive_ingredients":["ウンドルクエ","ギアル","ザソニカ"],"appearance":"青色澄明の液体を充填した透明ガラスバイアル (蓋に蝶のエンボス加工付、白色ラベル) (架空)","identification_code":null},"warning":[{"order":1,"sub_order":null,"content":"過量投与により深い昏睡を来すおそれがあるため、服用記録を厳格に管理すること (架空)"}],"contraindications":[{"order":1,"sub_order":null,"content":"重症呼吸機能障害のある患者 (架空)"},{"order":2,"sub_order":null,"content":"中枢神経抑制剤を過量服用中の患者 (架空)"},{"order":3,"sub_order":null,"content":"本剤の成分に対し過敏症の既往歴のある患者 (架空)"}],"indications":[{"order":1,"content":"不眠症 (架空)"}],"indications_related_precautions":[{"order":1,"sub_order":null,"content":"不眠の原因となる基礎疾患の検索を優先し、漫然と投与しないこと (架空)"}],"dosage":{"standard_dosage":"通常、成人には就寝直前に 1 回 1 mL を経口投与する (架空)","age_specific_dosage":[{"range":{"min_age_months":780,"max_age_months":null,"label":"65 歳以上"},"dose":"初回は 0.5 mL から開始し、状態を観察しながら慎重に投与する (架空)"}],"renal_adjustment":[{"range":{"min_ml_per_min":null,"max_ml_per_min":29,"severity":"severe","label":"30 mL/min 未満、重度腎機能低下"},"dose":"1 回 1 mL の投与間隔を延長し、過鎮静に注意する (架空)"}],"hepatic_adjustment":[{"severity":"moderate","dose":"0.5 mL から開始し、翌朝の持ち越し効果を確認する (架空)"}]},"dosage_related_precautions":[{"order":1,"sub_order":null,"content":"服用後は自動車の運転等危険を伴う機械の操作をしないこと (架空)"},{"order":2,"sub_order":null,"content":"アルコール及び他の中枢神経抑制剤との併用で作用が増強される (架空)"}],"important_precautions":[{"order":1,"sub_order":null,"content":"過量服用時は 24 時間以内の救命処置を要することがある (架空)"},{"order":2,"sub_order":null,"content":"翌朝の眠気、注意力低下及びふらつきに注意すること (架空)"}],"precautions_for_specific_populations":[{"category":"geriatric","note":"高齢者では転倒、せん妄及び持ち越し効果があらわれやすい (架空)"},{"category":"pregnant","note":"妊婦又は妊娠している可能性のある女性には治療上の有益性を慎重に判断する (架空)"},{"category":"lactating","note":"授乳中の投与は避け、やむを得ず投与する場合は授乳を中止する (架空)"},{"category":"pediatric","note":"小児等を対象とした安全性は確立していない (架空)"}],"interactions":{"combination_prohibited":[{"drug_id":null,"display_name":"アルコール大量併用","clinical_symptom":"深い鎮静又は昏睡が増強されるおそれがある (架空)","mechanism":"中枢神経抑制作用が相加的に増強される (架空)"}],"combination_caution":[{"drug_id":null,"display_name":"ベンゾジアゼピン系薬剤","clinical_symptom":"眠気、ふらつき及び呼吸抑制が増強されるおそれがある (架空)","mechanism":"GABA 作動性の抑制作用が重なる (架空)"},{"drug_id":null,"display_name":"オピオイド鎮痛薬","clinical_symptom":"呼吸抑制及び意識障害が増強されるおそれがある (架空)","mechanism":"呼吸中枢抑制作用が相加的に増強される (架空)"}]},"adverse_reactions":{"serious":[{"name":"呼吸抑制","frequency":"unknown","symptom":"過鎮静に伴い呼吸数低下を来すことがある (架空)","initial_signs":"強い眠気、呼びかけへの反応低下、浅い呼吸 (架空)","countermeasure":"投与を中止し気道確保及び呼吸管理を行う (架空)"},{"name":"依存性及び離脱症状","frequency":"unknown","symptom":"連用により依存を形成し、中止時に反跳性不眠を来すことがある (架空)","initial_signs":"服薬欲求、焦燥、不眠の増悪 (架空)","countermeasure":"急な中止を避け、状態を観察しながら漸減する (架空)"}],"other":{"over5_percent":["眠気","倦怠感"],"between1_and5_percent":["ふらつき","頭痛"],"under1_percent":["健忘"],"frequency_unknown":["悪夢"]}},"effects_on_lab_tests":[{"order":1,"sub_order":null,"content":"肝機能検査値の変動を認めることがある (架空)"}],"overdose":{"symptoms":"深い昏睡 (何があっても起きない状態)。即死には至らない (架空)","management":"24 時間以内の医療処置 (気道確保・対症療法・必要に応じて拮抗薬投与・全身管理) が必須 (架空)"},"administration_precautions":[{"order":1,"sub_order":null,"content":"青色着色は誤飲防止のためであり、他剤と取り違えないこと (架空)"},{"order":2,"sub_order":null,"content":"管理者立会いのもと、就寝直前に水で服用すること (架空)"}],"other_precautions":[{"order":1,"sub_order":null,"content":"連用により依存形成のおそれがあるため短期間の使用にとどめること (架空)"}],"pharmacokinetics":{"blood_concentration":"経口投与後、約 1 時間で最高血中濃度に到達する (架空)","absorption":"消化管から速やかに吸収される (架空)","distribution":"中枢神経系へ移行し催眠作用を示す (架空)","metabolism":"主として肝代謝により不活性化される (架空)","excretion":"代謝物として尿中へ排泄される (架空)","parameters":[{"name":"Cmax","value":"8.0 ng/mL"},{"name":"Tmax","value":"1.0 時間"},{"name":"T1/2","value":"2.4 時間"},{"name":"AUC","value":"24 ng・hr/mL"}]},"clinical_results":[{"heading":"不眠症患者対象試験","content":"不眠症患者を対象とした架空比較試験で睡眠潜時の短縮が示された (架空)"}],"pharmacology":{"mechanism":"GABA-A 受容体の部位に結合し神経活動を抑制する様式の催眠作用を示す (架空)","effect":"動物試験で睡眠潜時短縮及び睡眠時間延長を示した (架空)"},"physicochemical_properties":{"generic_name_english":"foshi'merc","molecular_formula":"C26H39N3O2S1Cl1","molecular_weight":null,"description":"青色澄明の液体で、誤飲防止のため青色に着色している (架空)"},"handling_precautions":[{"order":1,"sub_order":null,"content":"白色ラベルの記載を確認し、服用記録と残量を照合すること (架空)"},{"order":2,"sub_order":null,"content":"直射日光を避け、冷暗所で保管すること (架空)"}],"approval_conditions":[{"order":1,"sub_order":null,"content":"適切な睡眠薬管理体制を有する施設で使用すること (架空)"}],"packages":[{"size":"30 mL ガラス瓶 (蝶エンボス加工蓋・白色ラベル) (架空)","storage_condition":{"temperature":"room_temperature","light_protection":true,"moisture_protection":false,"additional_note":"冷暗所保管を推奨 (架空)"},"expiration_months":36}],"references":[{"citation":"ナギサ. 青色液剤型催眠薬の服薬管理に関する架空研究. 架空睡眠薬研究, 12, 345-348. (架空)","source":"架空睡眠薬研究"},{"citation":"ミハシ. 不眠症に対する短時間作用型催眠薬の架空比較試験. 架空臨床睡眠誌, 12, 345-348. (架空)","source":"架空臨床睡眠誌"},{"citation":"コウメ. 睡眠薬過量服用時の 24 時間管理に関する架空報告. 架空救急薬理, 12, 345-348. (架空)","source":"架空救急薬理"}],"insurance_notes":[{"order":1,"sub_order":null,"content":"向精神薬として投与日数及び服薬管理に注意すること (架空)"}],"manufacturer":"不明","revised_at":"2026-01-24","related_disease_ids":["disease_0022"],"image_url":"/v1/images/drugs/drug_0089?size=Original","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
